def calculate_deviation(p, n):
    return sum(abs(p[i] - (i + 1)) for i in range(n))

n = int(input())
p = list(map(int, input().split()))

min_deviation = float('inf')
min_id = 0

for k in range(n):
    # Create cyclic shift with k right shifts
    shifted = p[-k:] + p[:-k]
    dev = calculate_deviation(shifted, n)

    if dev < min_deviation:
        min_deviation = dev
        min_id = k

print(min_deviation, min_id)
"}

