    # Actually, we need to find the one that differs
    for i in range(n):
        if numbers[i] % 2 != first_parity:
            print(i + 1)
            exit()
else:
    # The one that differs has the same parity as the first number (since majority are different)
    for i in range(n):
        if numbers[i] % 2 == first_parity:
            print(i + 1)
            exit()
