n, m, c = input().split()
n = int(n)
m = int(m)

# Parse the matrix
data = []
for _ in range(n):
    row = list(input().strip())
    data.append(row)

# Find the president's desk
# Since desks are contiguous rectangles, we can find it by finding the first occurrence of 'c'
presidents_position = None
for i in range(n):
    for j in range(m):
        if data[i][j] == c:
            presidents_position = (i, j)
            break
    if presidents_position:
        break

# Find all desks and their coordinates
# We'll use a set to store all desk positions
desk_positions = set()

# Find all desks by checking contiguous regions
# We'll use a simple flood fill algorithm
visited = [[False for _ in range(m)] for _ in range(n)]

for i in range(n):
    for j in range(m):
        if data[i][j] != '.' and not visited[i][j]:
            # This is a new desk
            color = data[i][j]
            # Find all positions of this desk using flood fill
            queue = [(i, j)]
            visited[i][j] = True
            desk = set()
            while queue:
                x, y = queue.pop(0)
                desk.add((x, y))
                for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m:
                        if not visited[nx][ny] and data[nx][ny] == color:
                            visited[nx][ny] = True
                            queue.append((nx, ny))
            desk_positions.update(desk)

# Now find which desks are adjacent to the president's desk
# First, determine if each position belongs to the president's desk
president_desk = set()
for pos in desk_positions:
    x, y = pos
    if data[x][y] == c:
        president_desk.add(pos)

adjacent_desks = set()
for x, y in president_desk:
    for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        nx, ny = x + dx, y + dy
        if 0 <= nx < n and 0 <= ny < m:
            neighbor_color = data[nx][ny]
            if neighbor_color != '.' and neighbor_color != c:
                adjacent_desks.add(neighbor_color)

# Output the count
print(len(adjacent_desks))
"}

