def is_good(arr):
    if len(arr) <= 1:
        return True

    # Build the non-decreasing sequence by always choosing the smallest possible next element
    # from either end
    i, j = 0, len(arr) - 1
    last = -1

    while i <= j:
        # Choose the smallest possible next element
        if i <= j and arr[i] <= arr[j]:
            if arr[i] >= last:
                last = arr[i]
                i += 1
            else:
                return False
        else:
            if arr[j] >= last:
                last = arr[j]
                j -= 1
            else:
                return False

    return True

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        a = list(map(int, input().split()))

        for k in range(n + 1):
            if is_good(a[k:]):
                print(k)
                break

solve()
"}

