import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    # Count original number of 1s
    original_ones = sum(arr)

    # Find the subarray with maximum (number of 0s - number of 1s)
    max_gain = 0

    # For each starting position
    for start in range(n):
        count_0 = 0
