import math

def solve():
    line = input().strip()
    if not line:
        return
    parts = line.split()
    if len(parts) != 4:
        return
    n, m, a, b = map(int, parts)
    min_cost = n * a  # default: all single
    k_max = (n + m - 1) // m  # ceil(n/m)
    for k in range(0, k_max + 1):
        cost = b * k + a * max(0, n - k * m)
        if cost < min_cost:
            min_cost = cost
    print(min_cost)

if __name__ == "__main__":
    solve()
