def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def solve():
    n = int(input().strip())
    a = list(map(int, input().split()))

    # Count occurrences of 1
    ones_count = a.count(1)

    # Try to include as many even numbers as possible
    evens = [x for x in a if x % 2 == 0]
    odds = [x for x in a if x % 2 != 0]

    result = []

    # Case 1: Include both ones if available
    if ones_count >= 2:
        result.extend([1, 1])
        ones_count -= 2

    # Case 2: One 1 and even numbers
    elif ones_count == 1:
        # Try to include even numbers that when added to 1 produce a prime
        for even in evens:
            if is_prime(1 + even):
                result.append(1)
                result.append(even)
                evens.remove(even)
                break

    # Case 3: Include even numbers that sum to a prime (even + even = even, so only 2 works)
    else:
        # Try to include pairs of even numbers that sum to a prime
        for i in range(len(evens)):
            for j in range(i + 1, len(evens)):
                if is_prime(evens[i] + evens[j]):
                    result.append(evens[i])
                    result.append(evens[j])
                    evens.pop(j)
                    evens.pop(i)
                    break
            if len(result) >= 2:
                break

    print(len(result))
    if result:
        print(' '.join(map(str, result)))
    else:
        print()

solve()
