n, m = map(int, input().split())

constraints = []
for _ in range(m):
    l, r, q = map(int, input().split())
    constraints.append((l, r, q))

# Initialize array with all bits unset
array = [0] * n

# Try to set each bit position from lowest to highest
for b in range(30):
    # Try to set this bit in some elements

    # For each constraint:
    #   If bit b is set in q, then all elements in [l..r] must have this bit set
    #   If bit b is not set in q, then at least one element in [l..r] must have this bit cleared

    # Start by clearing this bit in all elements
    for i in range(n):
        array[i] &= ~(1 << b)

    # Try to set this bit in some elements while satisfying constraints
    for l, r, q in constraints:
        if (q >> b) & 1:
            # Bit b must be set in all elements of [l..r]
            for i in range(l-1, r):
                array[i] |= (1 << b)
        else:
            # Bit b must be cleared in at least one element of [l..r]
            # Try to find a position in [l..r] where we can clear this bit
            # We'll look for an element that currently has this bit set
            for i in range(l-1, r):
                if (array[i] & (1 << b)) != 0:
                    array[i] &= ~(1 << b)
                    break

# After setting all bits, check all constraints
all_satisfied = True
for l, r, q in constraints:
    and_result = 0
    for i in range(l-1, r):
        and_result &= array[i]
    if and_result != q:
        all_satisfied = False
        break

if all_satisfied:
    print("YES")
    print(' '.join(map(str, array)))
else:
    print("NO")
