import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    # Parse input
    data = list(map(int, data))
    n = data[0]
    m = data[1]

    # Build graph
    graph = defaultdict(list)
    for i in range(m):
        u = data[2 + 4*i]
        v = data[3 + 4*i]
        g = data[4 + 4*i]
        l = data[5 + 4*i]
        graph[u].append((v, g, l))
        graph[v].append((u, g, l))

    # Check if we can assign values
    assigned = {}  # node -> value
    valid = True

    # Try to assign values using BFS
    if n > 1:
        start = 1
        assigned[start] = 1

        # BFS to assign values
        queue = deque([start])
        while queue and valid:
            node = queue.popleft()
            for neighbor, g, l in graph[node]:
                if neighbor not in assigned:
                    # Calculate value for neighbor
                    val = assigned[node] * l // g
                    assigned[neighbor] = val
                    queue.append(neighbor)
                else:
                    # Check constraint with already assigned neighbor
                    a = assigned[node]
                    b = assigned[neighbor]
                    if (a == b and g != a) or (a == b and l != a):
                        valid = False
                    elif (a < b and g != a) or (a < b and l != a):
                        valid = False
                    elif (a > b and g != b) or (a > b and l != b):
                        valid = False

    if valid:
        # Verify all edges
        for u, v, g, l in edges:
            a = assigned.get(u, 1)
            b = assigned.get(v, 1)
            if a * b != g * l or gcd(a, b) != g or lcm(a, b) != l:
                valid = False
                break

    if valid:
        print("YES")
        for i in range(1, n + 1):
            print(assigned.get(i, 1), end=' ')
        print()
    else:
        print("NO")

