def solve():
    a, b, c = map(int, sys.stdin.readline().split())

    # Days that require each type of food
    fish_days = [0, 3, 1, 0, 0, 1, 3]  # Index 0 = Sunday, index 1 = Monday, ...
    rabbit_days = [1, 0, 0, 0, 1, 0, 0]
    chicken_days = [0, 0, 1, 1, 0, 0, 0]

    # For each possible starting day, find how many days we can go
    max_days = 0

    for start_day in range(7):
        fish_used = 0
        rabbit_used = 0
        chicken_used = 0

        days = 0

        while True:
            # Check if we have enough food for the next day
            if (start_day + days) % 7 == 0:
                # Fish food needed
                if a > fish_used:
                    fish_used += 1
                    days += 1
                else:
                    break
            elif (start_day + days) % 7 == 1:
                # Rabbit stew needed
                if b > rabbit_used:
                    rabbit_used += 1
                    days += 1
                else:
                    break
            else:
                # Chicken stake needed
                if c > chicken_used:
                    chicken_used += 1
                    days += 1
                else:
                    break

        max_days = max(max_days, days)

    print(max_days)

if __name__ == "__main__":
    solve()
