{"code": "
import sys

def solve():
    t = int(sys.stdin.readline())
    for _ in range(t):
        n = int(sys.stdin.readline())
        a = list(map(int, sys.stdin.readline().split()))

        freq = {}
        for num in a:
            freq[num] = freq.get(num, 0) + 1

        # Pair up equal numbers by adding 0 to balance
        pairs = []
        unpaired = []

        for num, count in freq.items():
            if count > 1:
                pairs.extend([num] * (count // 2))

        # Find unpaired elements
        unpaired = []
        for num, count in freq.items():
            if count % 2 == 1:
                unpaired.append(num)

        # If no unpaired elements, array is good
        if len(unpaired) == 0:
            print(0)
            print()
            continue

        # Otherwise, add elements
        added = []

        # Try adding one element to pair with an unpaired element
        for x in unpaired:
            added.append(x)
            added.append(x)
            break

        # Print result
        print(len(added))
        if added:
            print(' '.join(map(str, added)))

if __name__ == '__main__':
    solve()
"}

