        else:
            # Non-palindrome case
            # Alice reverses, Bob flips, Alice reverses, Bob flips, ...
            # Bob flips all '0's
            alice_cost = 0
            bob_cost = zeros

        if alice_cost < bob_cost:
            print("ALICE")
        elif alice_cost > bob_cost:
            print("BOB")
        else:
            print("DRAW")

solve()
