{"code": "
n, k = map(int, input().split())
questions = list(map(int, input().split()))

# Get positions of each cell in the questions (1-indexed)
positions = [[] for _ in range(n + 1)]
for idx, x in enumerate(questions):
    positions[x].append(idx + 1)

count = 0
for a in range(1, n + 1):
    # Check if a is a valid starting position
    # A valid start means no question is at position 1..k at cell a
    valid_start = True
    for idx in positions[a]:
        if idx > 0:  # a is guessed at position 1 or later
            valid_start = False
            break
    if not valid_start:
        continue

    # Try end positions b = a-1, a, a+1
    for b in range(a - 1, a + 2):
        if b < 1 or b > n:
            continue

        if a == b:
            # No move, just check if a is valid start
            count += 1
        else:
            # Check if there exists a split point t
            # such that prefix [1..t-1] has no a, and suffix [t..k] has no b
            # t can be 1 (move before first question) or k+1 (move after last question)
            can_move = False
            for t in range(1, k + 2):  # t ranges from 1 to k+1
                # Check prefix: all positions of a < t
                valid_prefix = True
                for idx in positions[a]:
                    if idx >= t:
                        valid_prefix = False
                        break
                if not valid_prefix:
                    continue

                # Check suffix: all positions of b >= t
                valid_suffix = True
                for idx in positions[b]:
                    if idx < t:
                        valid_suffix = False
                        break
                if valid_suffix:
                    can_move = True
                    break

            if can_move:
                count += 1

print(count)
"}

