    if j == empty_pos[1]:
        # Column with empty cell, we'll calculate separately
        col_sum = sum(grid[i][j] for i in range(n))
    else:
        col_sum = sum(grid[i][j] for i in range(n))
    col_sums.append(col_sum)

# Calculate sums of diagonals that do NOT contain the empty cell
