    # Base number of 1s per row, remainder
    base = k // n
    rem = k % n

    # Create grid
    grid = []
    for i in range(n):
        row = []
        for j in range(n):
            # Place base 1s in columns 0 to base-1
            # Add extra 1 if we need to (for first rem rows)
            if j < base:
                row.append('1')
            else:
                row.append('0')
        grid.append(''.join(row))

    # Add the remaining 1s to balance columns
    # We need to add 1 to the first rem rows
    # Let's add them to the first (n+1)//2 columns
    add_to = min(n, (n + 1) // 2)
    for i in range(rem):
        for j in range(add_to):
            if grid[i][j] == '1':
                grid[i] = grid[i][:j] + '0' + grid[i][j+1:]
            else:
                grid[i] = grid[i][:j] + '1' + grid[i][j+1:]

    # Compute row sums and column sums
    rows = [row.count('1') for row in grid]
    cols = [0] * n
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '1':
                cols[j] += 1

    max_r, min_r = max(rows), min(rows)
    max_c, min_c = max(cols), min(cols)

    f = (max_r - min_r) ** 2 + (max_c - min_c) ** 2

    print(f)
