{"code": "
def analyze(s, last_op, memo, alice_turn):
    # Base case: all '1's
    if s == '1' * len(s):
        return 0  # Cost for this player

    # Memoization
    key = (s, last_op, alice_turn)
    if key in memo:
        return memo[key]

    # Find the minimum cost for the current player
    if alice_turn:
        # Alice wants to minimize her cost
        min_cost = float('inf')
        # Option 1: change a '0' to '1'
        for i in range(len(s)):
            if s[i] == '0':
                new_s = s[:i] + '1' + s[i+1:]
                cost = 1 + analyze(new_s, 'change', memo, False)
                min_cost = min(min_cost, cost)
        # Option 2: reverse if allowed
        if last_op != 'reverse' and s != s[::-1]:
            cost = 0 + analyze(s[::-1], 'reverse', memo, False)
            min_cost = min(min_cost, cost)
        memo[key] = min_cost
        return min_cost
    else:
        # Bob wants to minimize his cost
        min_cost = float('inf')
        # Option 1: change a '0' to '1'
        for i in range(len(s)):
            if s[i] == '0':
                new_s = s[:i] + '1' + s[i+1:]
                cost = 1 + analyze(new_s, 'change', memo, True)
                min_cost = min(min_cost, cost)
        # Option 2: reverse if allowed
        if last_op != 'reverse' and s != s[::-1]:
            cost = 0 + analyze(s[::-1], 'reverse', memo, True)
            min_cost = min(min_cost, cost)
        memo[key] = min_cost
        return min_cost


def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())
        s = input().strip()

        # Initial state: string s, last operation not reverse, Alice's turn
        memo = {}
        alice_cost = analyze(s, 'not_reverse', memo, True)
        bob_cost = analyze(s, 'not_reverse', memo, False)

        if alice_cost < bob_cost:
            print("ALICE")
        elif alice_cost > bob_cost:
            print("BOB")
        else:
            print("DRAW")

solve()
