import sys

def solve()
    data = sys.stdin.read().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx]); m = int(data[idx+1]); x = int(data[idx+2]); y = int(data[idx+3])
        idx += 4

        # We need to read the grid
        grid = []
        for i in range(n):
            line = data[idx]
            grid.append(line)
            idx += 1

        cost = 0

        # Check if 1x2 tiles are cheaper than two 1x1 tiles
        if y < 2 * x:
            # Use 1x2 tiles for adjacent pairs
            for row in range(n):
                pos = 0
                while pos < m - 1:
                    if grid[row][pos] == '.' and grid[row][pos+1] == '.':
                        # Found an adjacent pair
                        cost += y
                        pos += 2  # Skip both squares
                    else:
                        pos += 1
        else:
            # Just use 1x1 tiles for all '.'
            for row in range(n):
                for col in range(m):
                    if grid[row][col] == '.':
                        cost += x

        print(cost)

if __name__ == "__main__":
    solve()
