    idx = 3
    for _ in range(m):
        l = int(data[idx])
        r = int(data[idx + 1])
        c = int(data[idx + 2])
        companies.append((c, l, r))
        idx += 3

    # Sort companies by cost
    companies.sort()

    # Greedy approach: always cover the leftmost uncovered hole with the
    # cheapest company that covers it
    covered = set()
    cost = 0

    for pos in range(1, n + 1):
        if pos not in covered:
            # Find the cheapest company that covers this position
            for c, l, r in companies:
                if l <= pos <= r:
                    cost += c
                    for hole in range(l, r + 1):
                        covered.add(hole)
                    break

        # If we've covered enough holes, break early
        if len(covered) >= k:
            break

    if len(covered) >= k:
        print(cost)
    else:
        print(-1)

