def solve(l_a, r_a, t_a, l_b, r_b, t_b):
    # Find the maximum number of consecutive days lucky for both
    # A day x is lucky for both if:
    # - x % t_a is in [l_a, r_a]
    # - AND x % t_b is in [l_b, r_b]

    lcm = t_a * t_b // gcd(t_a, t_b)

    lucky_for_both = []
    for x in range(lcm):
        if l_a <= x % t_a <= r_a and l_b <= x % t_b <= r_b:
            lucky_for_both.append(x)

    lucky_for_both = sorted(lucky_for_both)

    if not lucky_for_both:
        return 0

    max_consecutive = 1
    current = 1

    for i in range(1, len(lucky_for_both)):
        if lucky_for_both[i] == lucky_for_both[i-1] + 1:
            current += 1
            max_consecutive = max(max_consecutive, current)
        else:
            current = 1

    return max_consecutive

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    l_a, r_a, t_a = map(int, data[0:3])
    l_b, r_b, t_b = map(int, data[3:6])

    result = solve(l_a, r_a, t_a, l_b, r_b, t_b)
    print(result)

if __name__ == "__main__":
    main()
"}

