import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n, k, m = int(data[idx]), int(data[idx+1]), int(data[idx+2])
    idx += 3

    # Count frequency of each remainder modulo m
    freq = {}
    for i in range(n):
        num = int(data[idx + i])
        rem = num % m
        freq[rem] = freq.get(rem, 0) + 1

    # Find if any remainder has at least k occurrences
    found = False
    result = []

    for rem, cnt in freq.items():
        if cnt >= k:
            found = True
            result = [rem] * k  # We need any k numbers with this remainder
            break

    if found:
        print("Yes")
        print(" ".join(map(str, result)))
    else:
        print("No")

if __name__ == "__main__":
    solve()
"}

