import sys
import math
from collections import defaultdict

def is_prime(n):
    """Check if n is a prime number."""
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    sqrt_n = int(math.sqrt(n)) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count occurrences of 1
    count_ones = a.count(1)

    # For elements > 1, separate by parity
    even = []
    odd = []
    for num in a:
        if num > 1:
            if num % 2 == 0:
                even.append(num)
            else:
                odd.append(num)

    # Try taking all 1s plus one other element if it forms a valid pair with all 1s
    if count_ones >= 2:
        best = count_ones
        if even:
            valid = True
            for x in even:
                # Check if x forms a valid pair with all 1s (1+x must be prime)
                for y in a[:count_ones]:  # all 1s
                    if not is_prime(1 + y):
                        valid = False
                        break
                if valid:
                    best = count_ones + 1
                    break
        if odd:
            valid = True
            for x in odd:
                # Check if x forms a valid pair with all 1s (1+x must be prime)
                for y in a[:count_ones]:
                    if not is_prime(1 + y):
                        valid = False
                        break
                if valid:
                    best = count_ones + 1
                    break

        # Also consider taking a subset of all even or odd numbers
        # where all pairwise sums are prime
        def check_subset(sub):
            for i in range(len(sub)):
                for j in range(i + 1, len(sub)):
                    if not is_prime(sub[i] + sub[j]):
                        return False
            return True

        if even and check_subset(even):
            best = max(best, len(even))
        if odd and check_subset(odd):
            best = max(best, len(odd))

        # Output the result
        if best == count_ones:
            print(best)
            print(' '.join(['1'] * best))
        else:
            # Try to find a valid subset with best size
            if best == count_ones + 1:
                # All 1s plus one other element
                print(best)
                print(' '.join(['1'] * count_ones + [str(a[i]) for i in range(n) if a[i] > 1 and all(is_prime(1 + a[j]) for j in range(n) if a[j] == 1)]))
            else:
                # Subset of all even or all odd
                if even and len(even) >= best:
                    print(best)
                    print(' '.join(map(str, even[:best])))
                else:
                    print(best)
                    print(' '.join(map(str, odd[:best])))
        return

    # If no 1s or only one 1, we need to find a valid subset of size 2 at most
    # Check all pairs
    primes = set()
    for i in range(n):
        for j in range(i + 1, n):
            if is_prime(a[i] + a[j]):
                primes.add((a[i], a[j]))

    if primes:
        print(2)
        print(primes.pop())
    else:
        print(1)
        print(a[0])

