import sys

def get_divisors(n):
    """Get all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def solve() -> None:
    input = sys.stdin.read().split()
    if not input:
        return

    n = int(input[0])
    idx = 1

    # Precompute divisors for numbers up to 10000
    max_x = 10000
    divisors_cache = {}
    for i in range(1, max_x + 1):
        divisors_cache[i] = get_divisors(i)

    output = []

    for query_num in range(1, n + 1):
        xi = int(input[idx])
        yi = int(input[idx + 1])
        idx += 2

        if yi == 0:
            # Answer is number of divisors of xi
            output.append(str(len(divisors_cache[xi])))
        else:
            # Check which divisors of xi don't divide any number in [xi - yi, xi - 1]
            answer = 0
            xi_minus_yi = xi - yi

            for d in divisors_cache[xi]:
                # Check if d divides any number in the range
                divides_any = False
                for num in range(xi_minus_yi, xi):
                    if num % d == 0:
                        divides_any = True
                        break
                if not divides_any:
                    answer += 1

            output.append(str(answer))

    print("\n".join(output))

if __name__ == "__main__":
    solve()
