n, k = map(int, input().split())
x = list(map(int, input().split()))

# Set of forbidden positions at each time
forbidden = [x_i for x_i in x]

# Build forbidden matrix: if Alice is at position i at time t, that's not allowed
# We need to count (a, b) where |a - b| <= 1
# And there's a path from a to b such that for each time t, we're not at forbidden[t]

# Initialize DP table: dp[t][i] = True if we can be at position i at time t
# Without hitting any forbidden positions so far

dp = [[False] * (n + 2) for _ in range(k + 1)]  # dp[0][a] = True for all a
for i in range(1, n + 2):
    dp[0][i] = True

# Update DP table for each time step
for t in range(k):
    for i in range(1, n + 2):
        # Can we be at position i at time t?
        # We need to have been at an adjacent position at time t-1
        if dp[t][i]:
            continue
        if forbidden[t] == i:
            continue  # This position is forbidden
        for j in [i - 1, i, i + 1]:
            if j < 1 or j > n:
                continue
            if dp[t - 1][j]:
                dp[t][i] = True
                break

# Now count all (a, b) where |a - b| <= 1 and dp[k][b] is True
answer = 0
for a in range(1, n + 1):
    for b in range(a - 1, a + 2):
        if 1 <= b <= n and dp[k][b]:
            answer += 1

print(answer)
"}

