# s=0: we haven't moved yet (position at time 0)
# s=1: we've moved (position at time 0)
# dp[t][i][s] = True if we can be at i at time t

dp = [[[False] * 2 for _ in range(n + 1)] for _ in range(k + 1)]

# Base case: at time 0, we can be at any position with state 0 (position at time 0)
for a in range(1, n + 1):
    dp[0][a][0] = True

# Update DP table for each time step
for t in range(1, k + 1):
    for i in range(1, n + 1):
        # State 0: we haven't moved yet
        if forbidden[t] != i:
            # We can be at i if we were at an adjacent position at time t-1 in state 0
            # Or we could have stayed at our original position from time 0
            if i - 1 >= 1 and dp[t - 1][i - 1][0]:
                dp[t][i][0] = True
            elif i + 1 <= n and dp[t - 1][i + 1][0]:
                dp[t][i][0] = True
            elif i >= 1 and dp[0][i][0]:
                dp[t][i][0] = True

        # State 1: we've already moved
        if forbidden[t] != i:
            # We can be at i if we were at an adjacent position at time t-1 in state 1
            if i - 1 >= 1 and dp[t - 1][i - 1][1]:
                dp[t][i][1] = True
            elif i + 1 <= n and dp[t - 1][i + 1][1]:
                dp[t][i][1] = True

# Count all (a, b) where |a - b| <= 1 and there's a path from a to b
answer = 0
for a in range(1, n + 1):
    for b in range(a - 1, a + 2):
        if 1 <= b <= n:
            if dp[k][b][0]:  # path never moved
                answer += 1
            if dp[k][b][1]:  # path moved at some point
                answer += 1

print(answer)
