# dp[t][i]: at time t, can we be at position i without being at a forbidden position?

dp = [[False] * (n + 1) for _ in range(k + 1)]

# Base case: at time 0, we can be at any starting position
for a in range(1, n + 1):
    dp[0][a] = True

# Update DP table for each time step
for t in range(1, k + 1):
    for i in range(1, n + 1):
        if forbidden[t] == i:
            continue  # This position is forbidden at this time
        # We can be at i if we were at an adjacent position at time t-1
        # or if we stay at the same position (since we can move at most once)
        # actually we can stay at the same position indefinitely if we haven't moved
        # So we need to allow staying at position i
        if dp[t - 1][i]:
            dp[t][i] = True
        elif i - 1 >= 1 and dp[t - 1][i - 1]:
            dp[t][i] = True
        elif i + 1 <= n and dp[t - 1][i + 1]:
            dp[t][i] = True

# Count all (a, b) where |a - b| <= 1 and there's a path from a to b
answer = 0
for a in range(1, n + 1):
    for b in range(a - 1, a + 2):
        if 1 <= b <= n and dp[k][b]:
            answer += 1

print(answer)

