# Dictionaries to track children
left_child = {}
right_child = {}

# Dictionary to map each value to its parent
parent = {}

# Start with the root
root = a[0]
parent[a[0]] = None
left_child[a[0]] = None
right_child[a[0]] = None

for i in range(1, n):
    val = a[i]
    current = root

    # Traverse to find where val should go
    while True:
        if val > current:
            if right_child[current] is None:
                # Create right child
                parent[val] = current
                right_child[current] = val
                break
            else:
                # Move to right child
                current = right_child[current]
        else:
            if left_child[current] is None:
                # Create left child
                parent[val] = current
                left_child[current] = val
                break
            else:
                # Move to left child
                current = left_child[current]

# Output the parents for values 2 to n
output = []
for i in range(1, n):
    output.append(str(parent[a[i]]))

print(" ".join(output))
