    """Check if seq1 appears before seq2 (with space in between) in string s"""
    # Find all occurrences of seq1
    seq1_indices = []
    n = len(seq1)
    for i in range(len(s) - n + 1):
        if s[i:i+n] == seq1:
            seq1_indices.append(i)

    # Check if any seq1 occurrence is followed by seq2
    for i in seq1_indices:
        # seq2 must start after seq1 ends
        for j in range(i + n, len(s) - n + 1):
            if s[j:j+n] == seq2:
                return True
    return False

def solve():
    s = input().strip()
    seq1 = input().strip()
    seq2 = input().strip()

    # Check forward direction (A to B)
    forward = can_see(s, seq1, seq2)

    # Check backward direction (B to A)
    # In reverse, we need to check if seq2 comes before seq1
    backward = can_see(s[::-1], seq2, seq1)

    if forward and backward:
        print("both")
    elif forward:
        print("forward")
    elif backward:
        print("backward")
    else:
