class TreeNode:
    def __init__(self, value):
        self.value = value
        self.left = None
        self.right = None


def build_bst(values):
    if not values:
        return None

    root = TreeNode(values[0])
    parent_map = {values[0]: None}  # key: node value, value: parent value

    for i in range(1, len(values)):
        current = root
        parent = None

        # Traverse to find the parent
        while current is not None:
            parent = current
            if values[i] > current.value:
                current = current.right
            else:
                current = current.left

        # We found the parent, now insert the new node
        node = TreeNode(values[i])
        parent_map[values[i]] = parent.value

        # Add to the parent's left/right
        if values[i] > parent.value:
            parent.right = node
        else:
            parent.left = node

    return parent_map


def main():
    import sys
    input = sys.stdin.read().split()

    if not input:
        return

    n = int(input[0])
    values = list(map(int, input[1:]))

    parent_map = build_bst(values)

    # Output all parent values except the first (which has no parent)
    for i in range(1, n):
        print(parent_map[values[i]], end=' ')
    print()

if __name__ == "__main__":
    main()

