        for _ in range(n):
            row = next(it)
            grid.append(row)

        total_cost = 0

        for row in range(n):
            i = 0
            while i < m:
                # Check if current cell is white
                if grid[row][i] == '.':
                    # If the next cell is also white and we can cover both
                    if i + 1 < m and grid[row][i + 1] == '.':
                        # Compare cost of two 1x1 vs one 1x2
                        if 2 * x < y:
                            total_cost += 2 * x
                        else:
                            total_cost += y
                        i += 2
                    else:
                        # Use one 1x1 tile
                        total_cost += x
                        i += 1
                else:
                    # Skip black square
                    i += 1

        out_lines.append(str(total_cost))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
