suffixes = []
for i in range(len(a), -1, -1):
    if i == 0:
        suffixes.append('')  # empty string
    else:
        suffixes.append(a[i-1:])

# Check each suffix
for suffix in suffixes:
    # Check if b is exactly this suffix
    if b == suffix:
        print("YES")
        exit()

    # Check if b has the same parity as this suffix
    parity_suffix = sum(1 for c in suffix if c == '1') % 2
    parity_b = sum(1 for c in b if c == '1') % 2

    if parity_suffix != parity_b:
        continue

    # Check if b starts with this suffix and the remaining part has only parity_suffix
    # Edge case: if suffix is empty, we can make any length by writing bits
    # So we don't need to check remaining
    if suffix == "":
        if len(suffix) == 0 and len(b) > 0:
            # From empty, we can only write 0's
            if all(c == '0' for c in b):
                print("YES")
                exit()
    else:
        if len(suffix) >= len(b):
            # suffix is longer than b, can't start with b
            continue
        if b.startswith(suffix):
            remaining = b[len(suffix):]
            # All remaining characters should be parity_suffix
            if all(c == str(parity_suffix) for c in remaining):
                print("YES")
                exit()

print("NO")
