import sys

def get_divisors(n):
    """Return all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def solve():
    input = sys.stdin.read().strip().split()
    if not input:
        return

    n = int(input[0])

    # Precompute divisors for all numbers up to 105
    max_x = 105
    divisors = {}
    for x in range(1, max_x + 1):
        divisors[x] = get_divisors(x)

    idx = 1
    for _ in range(n):
        xi = int(input[idx])
        yi = int(input[idx + 1])
        idx += 2

        if yi == 0:
            # Count all divisors of xi
            answer = len(divisors[xi])
        else:
            # Count divisors of xi that do NOT divide any number in [xi - yi, xi - 1]
            xi_divisors = divisors[xi]
            answer = 0
            for d in xi_divisors:
                # Check if d divides any number in [xi - yi, xi - 1]
                divides_any = False
                for num in range(xi - yi, xi):
                    if num % d == 0:
                        divides_any = True
                        break
                if not divides_any:
                    answer += 1

        print(answer)

if __name__ == "__main__":
    solve()
