import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # For each bit position, we'll track which positions must have this bit set
    # Initially, all bits are unset
    bit_set = [set() for _ in range(30)]

    # Process constraints
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        q = int(next(it))

        # For each bit that must be set
        for bit in range(30):
            if q & (1 << bit):
                # This bit must be set in all positions from l to r
                for pos in range(l - 1, r):
                    bit_set[bit].add(pos)

    # Check consistency
    for bit in range(30):
        # If a bit must be set in some position but also not set in that position
        pos_set = bit_set[bit]
        if pos_set:
            # Check if there's any position that needs this bit set but already has it set
