import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    # Store all constraints
    constraints = []
    for _ in range(m):
        l = int(next(it))
        r = int(next(it))
        q = int(next(it))
        constraints.append((l, r, q))

    # For each bit position, we'll track:
    # - Positions that must have this bit set
    bit_must_set = [set() for _ in range(30)]

    # Process constraints
    for l, r, q in constraints:
        for bit in range(30):
            if q & (1 << bit):
                # This bit must be set in all positions from l to r
                for pos in range(l - 1, r):
                    bit_must_set[bit].add(pos)

    # Check for conflicts
    for bit in range(30):
        must_set = bit_must_set[bit]
        # For each position that must have this bit set, check if there's any constraint
        # where q doesn't have this bit set and this position is in that constraint's range
        for pos in must_set:
            for l, r, q in constraints:
                if not (q & (1 << bit)):
                    if l <= pos + 1 <= r:
                        print("NO")
                        return

    # Construct the array
    a = [0] * n
    for bit in range(30):
        if bit_must_set[bit]:
            for pos in bit_must_set[bit]:
                a[pos] |= 1 << bit

    print("YES")
    print(" ".join(map(str, a)))

if __name__ == "__main__":
    solve()

