def solve():
    S = input().strip()
    T = input().strip()
    MOD = 998244353

    # Check if T is a subsequence of S
    i = 0  # pointer in T
    for ch in S:
        if i < len(T) and ch == T[i]:
            i += 1

    if i != len(T):
        # T is not a subsequence, answer is 0
        print(0)
        return

    # DP[i]: number of operation sequences where A matches the first i characters of T
    dp = [0] * (len(T) + 1)
    dp[0] = 1

    # For each character we might take from S
    for j in range(len(S)):
        # For each state (i)
        for i in range(len(T), -1, -1):
            if i == len(T):
                # If we've already matched all of T, we just carry forward
                dp[i] = dp[i]
            else:
                # Add the current character to the front
                if S[j] == T[i]:
                    dp[i+1] = (dp[i+1] + dp[i]) % MOD

                # Add the current character to the back
                if S[j] == T[i]:
                    dp[i+1] = (dp[i+1] + dp[i]) % MOD


    print(dp[len(T)])

solve()
