n, m = map(int, input().split())

# Read banned cells
banned = set()
for _ in range(m):
    x, y = map(int, input().split())
    banned.add((x, y))

valid = []

# Check if a cell is valid
for r in range(1, n + 1):
    for c in range(1, n + 1):
        # Check if it's on the border but not a corner
        if (r == 1 or r == n or c == 1 or c == n) and not (r == 1 and c == 1) and not (r == 1 and c == n) and not (r == n and c == 1) and not (r == n and c == n):
            # Check if path is clear
            path_clear = True
            for i in range(min(r, n - r + 1) + 1):
                current_r = r + i * (1 if r != n else -1)
                current_c = c
                if (current_r, current_c) in banned:
                    path_clear = False
                    break
            if path_clear:
                # Check if opposite edge is clear
                if r != 1 and r != n:
                    opposite_r = 2 * n - r
                    opposite_c = c
                    if (opposite_r, opposite_c) in banned:
                        continue
                if c != 1 and c != n:
                    opposite_r = r
                    opposite_c = 2 * n - c
                    if (opposite_r, opposite_c) in banned:
                        continue
                # It's a valid cell
                valid.append((r, c))

# If n is odd, we can only place one chip at most
# If n is even, we can place chips on opposite edges
result = 0
if n % 2 == 1:
    # For odd n, we can only place one chip
    if valid:
        result = 1
elif n % 2 == 0:
    # For even n, we can place chips on opposite edges
    # Find valid pairs
    used = set()
    for i in range(len(valid)):
        if valid[i] in used:
            continue
        r1, c1 = valid[i]
        # Check top/bottom
        r2 = 2 * n - r1
        c2 = c1
        if c1 != 1 and c1 != n:
            if (r2, c2) in valid and (r2, c2) not in used:
                used.add((r1, c1))
                used.add((r2, c2))
                result += 2
        # Check left/right
        r3 = r1
        c3 = 2 * n - c1
        if r1 != 1 and r1 != n:
            if (r3, c3) in valid and (r3, c3) not in used:
                used.add((r1, c1))
                used.add((r3, c3))
                result += 2
    # Also add any single chips
    for cell in valid:
        if cell not in used:
            result += 1

print(result)
