    for c in range(1, n + 1):
        # Check if it's on the border but not a corner
        if (r == 1 or r == n or c == 1 or c == n) and not (r == 1 and c == 1) and not (r == 1 and c == n) and not (r == n and c == 1) and not (r == n and c == n):
            # Check if path is clear
            path_clear = True
            for i in range(min(r, n - r + 1) + 1):
                current_r = r + i * (1 if r != n else -1)
                current_c = c
                if (current_r, current_c) in banned:
                    path_clear = False
                    break
            if path_clear:
                # Check if opposite edge is clear
                if r != 1 and r != n:
                    opposite_r = 2 * n - r
                    opposite_c = c
                    if (opposite_r, opposite_c) in banned:
                        continue
                if c != 1 and c != n:
                    opposite_r = r
                    opposite_c = 2 * n - c
                    if (opposite_r, opposite_c) in banned:
                        continue
                # It's a valid cell
                valid.append((r, c))

# If n is odd, we can only place one chip at most
# If n is even, we can place chips on opposite edges
result = 0
if n % 2 == 1:
    # For odd n, we can only place one chip
    if valid:
        result = 1
elif n % 2 == 0:
    # For even n, we can place chips on opposite edges
    # We can place at most 2 chips (one on each edge type)
    result = 0
    if valid:
