def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    total = sum(a)

    # Check if it's possible
    # We need to make all boxes divisible by some k > 1
    if total < 2:
        print(-1)
        return

    min_cost = float('inf')

    # Try all possible k from 2 to total
    for k in range(2, total + 1):
        # Calculate prefix sums
        prefix = [0] * (n + 1)
        for i in range(1, n + 1):
            prefix[i] = prefix[i - 1] + a[i - 1]

        # DP state: dp[i][r] = minimum cost to make boxes 1..i have total remainder r mod k
        # where r is the remainder when dividing the total in boxes 1..i by k
        dp = [[float('inf')] * k for _ in range(n + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for r in range(k):
