                    move = abs(r - pr)
                    dp[i][r] = min(dp[i][r], dp[i - 1][pr] + move)

        if dp[n][0] < float('inf'):
            min_cost = min(min_cost, dp[n][0])

    print(min_cost if min_cost != float('inf') else -1)

