def is_possible_cycle(s, cycle):
    """Check if sequence s could be at position pos in the cycle"""
    if pos > len(cycle) - 1:
        return False

    for i in range(len(s)):
        if s[i] != cycle[(pos + i) % len(cycle)]:
            return False
    return True


def find_positions(s, cycle):
    """Find all positions in the cycle where sequence s could be"""
    positions = []
    for pos in range(len(cycle) - len(s) + 1):
        if is_possible_cycle(s, cycle, pos):
            positions.append(pos)
    return positions


def next_day_size(pos, cycle):
    """Get the next day's size given current position in the cycle"""
    return cycle[(pos + len(s)) % len(cycle)]


