        # Next day after 15 is always 14
        print("DOWN")
    elif 0 in a:
        # Next day after 0 is always 1
        print("UP")
    else:
        if len(positions) == 1:
            # Only one possible position
            next_size = next_day_size(positions[0], cycle)
            if next_size < a[-1]:
                print("DOWN")
            elif next_size > a[-1]:
                print("UP")
            else:
                print(-1)
        else:
            # Multiple possible positions
            print(-1)

