# If we can pack all objects in m boxes, return n
if n <= m:  # At most one object per box
    # Just try to pack them
    def can_pack(objects, m_boxes, box_size):
        boxes = 0
        current = 0
        for obj in objects:
            if current + obj <= box_size:
                current += obj
            else:
                boxes += 1
                current = obj
                if boxes >= m_boxes:
                    return False
        return True

    if can_pack(a, m, k):
        print(n)
        exit()

# Otherwise, we need to find the maximum number of objects we can pack
# We'll try a sliding window approach but correctly handle the two pointers
left = 0
right = n - 1
ans = 0

# Use a helper function to check if we can pack a certain range
def can_pack_range(left, right):
    boxes = 0
    current = 0
    for i in range(left, right + 1):
        if current + a[i] <= k:
            current += a[i]
        else:
            boxes += 1
            current = a[i]
            if boxes >= m:
                return False
    return True

while left < right:
    if can_pack_range(left, right):
        # We can pack this range, try to expand
        left += 1
        ans = max(ans, right - left + 1)
    else:
        # We cannot pack this range, try to shrink
        right -= 1
        ans = max(ans, right - left + 1)

print(ans)
