    grid = []
    empty_i, empty_j = -1, -1

    for i in range(n):
        row = list(map(int, sys.stdin.readline().split()))
        empty_i, empty_j = i, row.index(0)
        grid.append(row)

    # Calculate sum of completely filled rows/columns/diagonals
    row_sums = []
    col_sums = []
    diag1_sum = 0
    diag2_sum = 0

    for i in range(n):
        if i == empty_i:
            continue
        row_sums.append(sum(grid[i]))

    for j in range(n):
        if j == empty_j:
            continue
        col_sums.append(sum([grid[i][j] for i in range(n)]))

    # Check if all completely filled rows have the same sum
    if not row_sums or all(s == row_sums[0] for s in row_sums):
        target_row_sum = row_sums[0]
    else:
        print(-1)
        return

    # Check if all completely filled columns have the same sum
    if not col_sums or all(s == col_sums[0] for s in col_sums):
        target_col_sum = col_sums[0]
    else:
        print(-1)
        return

    # Check if diagonals (excluding empty cell) are consistent
    for i in range(n):
        if i == empty_i:
            continue
        if abs(i - empty_i) == abs(j - empty_j):  # diagonal 1 (i, j) to (i+1, j+1)
            diag1_sum += grid[i][j]
        if i + j == empty_i + empty_j:  # diagonal 2 (i, j) to (i+1, j-1)
            diag2_sum += grid[i][j]

    # Check if diagonals are consistent
    if abs(empty_i - empty_j) == abs(empty_i - empty_j):  # if empty cell is on diagonal 1
        if diag1_sum == target_row_sum and diag1_sum == target_col_sum:
            needed_diag1 = target_row_sum
        else:
            print(-1)
            return
    else:
        needed_diag1 = -1

    if empty_i + empty_j == n - 1:  # if empty cell is on diagonal 2
        if diag2_sum == target_row_sum and diag2_sum == target_col_sum:
            needed_diag2 = target_row_sum
        else:
            print(-1)
            return
    else:
        needed_diag2 = -1

    # Check if other diagonals are consistent
    if needed_diag1 != -1:
        for i in range(n):
            if i == empty_i:
                continue
            if abs(i - empty_i) == abs(empty_j - empty_j):  # diagonal 1 (i, j) to (i+1, j+1)
                if sum([grid[empty_i + k][empty_j + k] for k in range(n) if empty_i + k < n and empty_j + k < n]) != needed_diag1:
                    print(-1)
                    return

    if needed_diag2 != -1:
        for i in range(n):
            if i == empty_i:
                continue
            if i + j == empty_i + empty_j:  # diagonal 2 (i, j) to (i+1, j-1)
                if sum([grid[empty_i + k][empty_j - k] for k in range(n) if empty_i + k < n and empty_j - k >= 0]) != needed_diag2:
                    print(-1)
                    return

    # Calculate x
    row_sum = sum(grid[empty_i])
    col_sum = sum([grid[i][empty_j] for i in range(n)])

    needed_row = target_row_sum
    needed_col = target_col_sum
    needed_diag1 = target_row_sum if abs(empty_i - empty_j) == abs(empty_i - empty_j) else -1
    needed_diag2 = target_row_sum if empty_i + empty_j == n - 1 else -1

    if needed_row != needed_col or needed_row != needed_diag1 or needed_row != needed_diag2:
        print(-1)
        return

    # Check if target_row_sum equals the diagonal sums
    if needed_diag1 != -1 and sum(grid[empty_i][empty_j]) != needed_diag1:
        print(-1)
        return

    if needed_diag2 != -1 and sum(grid[empty_i][empty_j]) != needed_diag2:
        print(-1)
        return

    x = needed_row - row_sum
    if x <= 0:
        print(-1)
        return

    print(x)

