for li in range(n + 1):
    for lj in range(m + 1):
        total_time = 0

        for i in range(n):
            for j in range(m):
                # Yura's position: (li, lj) where li ∈ {0, 1, ..., n}, lj ∈ {0, 1, ..., m}
                # Square (i, j) is at coordinates (4*(j-1) + 2, 4*(i-1) + 2)

                # Distance squared = (x1 - x2)^2 + (y1 - y2)^2
                # Yura's position: (4*lj, 4*li)

                dx = (4 * (lj - j) + 2) ** 2
                dy = (4 * (li - i) + 2) ** 2

                total_time += c[i][j] * (dx + dy)

        if total_time < min_total_time:
