def solve():
    t = int(input())
    for _ in range(t):
        n, m, x, y = map(int, input().split())
        grid = []
        for _ in range(n):
            grid.append(input().strip())

        total_cost = 0

        for row in grid:
            # Find all groups of consecutive white squares
            groups = []
            start = None
            for i, ch in enumerate(row):
                if ch == '.':
                    if start is None:
                        start = i
                else:
                    if start is not None:
                        groups.append((start, i-1))
                        start = None

            # Check if there's a remaining group
            if start is not None:
                groups.append((start, len(row)-1))

            # Calculate cost for each group
            for s, e in groups:
                k = e - s + 1  # number of white squares in this group
                cost_1x1 = k * x
                cost_1x2 = (k + 1) // 2 * y  # ceil(k/2)
                total_cost += min(cost_1x1, cost_1x2)

        print(total_cost)

solve()
