def solve():
    # Read input
    n, m = map(int, input().split())
    grid = []
    for _ in range(n):
        grid.append(list(map(int, input().split())))

    # Check consistency: For each cell, g[i][j] should be consistent
    # If we perform r row moves and c column moves, we get r_i + c_j = g[i][j]
    # We can check if grid is consistent by ensuring that g[i][j] = g[i][0] + g[0][j] - g[0][0]

    # Check if grid is consistent
    is_consistent = True
    for i in range(n):
        for j in range(m):
            expected = grid[i][0] + grid[0][j] - grid[0][0]
            if grid[i][j] != expected:
                is_consistent = False
                break
        if not is_consistent:
            break

    if not is_consistent:
        print(-1)
        return

    # Find minimum moves
    # Strategy: For each row, set r_i = max(0, grid[i][0] - grid[0][0])
    # Then compute c_j = grid[0][j] - r_0

    r = [0] * n
    r[0] = max(0, grid[0][0])  # at least grid[0][0] row moves on row 0
    for i in range(1, n):
        r[i] = max(0, grid[i][0] - grid[0][0])

    c = [0] * m
    for j in range(m):
        c[j] = grid[0][j] - r[0]

    # Verify solution
    for i in range(n):
        for j in range(m):
            if grid[i][j] != r[i] + c[j]:
                print(-1)
                return

    # Output solution
    print(sum(r) + sum(c))
    for i in range(n):
        for _ in range(r[i]):
            print(f"row {i + 1}")
    for j in range(m):
        for _ in range(c[j]):
            print(f"col {j + 1}")

