def solve():
    t = int(input())

    for _ in range(t):
        n = int(input())
        s = input().strip()

        count_0 = s.count('0')

        # If the string is a palindrome
        if s == s[::-1]:
            # Alice pays 2 if even, 2 if odd (minimum cost to win)
            # Bob pays 0 if even, 1 if odd
            if count_0 % 2 == 0:
                alice_cost = 2
                bob_cost = 0
            else:
                alice_cost = 2
                bob_cost = 1

            if alice_cost < bob_cost:
                print("ALICE")
            elif alice_cost > bob_cost:
                print("BOB")
            else:
                print("DRAW")
        else:
