import sys

class TrieNode:
    def __init__(self):
        self.left = None  # 0 bit
        self.right = None  # 1 bit
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def add(self, num):
        node = self.root
        for bit in range(31, -1, -1):
            b = (num >> bit) & 1
            if not node.left and b == 0:
                node.left = TrieNode()
            if not node.right and b == 1:
                node.right = TrieNode()
            node = node.left if b == 0 else node.right
            node.count += 1

    def remove(self, num):
        node = self.root
        for bit in range(31, -1, -1):
            b = (num >> bit) & 1
            node = node.left if b == 0 else node.right
            node.count -= 1

    def count_leq(self, p, l):
        def dfs(node, bit, tight):
            if node is None:
                return 0
            if bit == -1:
                return node.count
            p_bit = (p >> bit) & 1
            l_bit = (l >> bit) & 1
            res = 0
            # Check left (0 bit)
            x0 = p_bit ^ 0
            if x0 < l_bit:
                if node.left:
                    res += node.left.count
            elif x0 == l_bit:
                res += dfs(node.left, bit-1, 1)
            else:
                pass  # x0 > l_bit, skip
            # Check right (1 bit)
            x1 = p_bit ^ 1
            if x1 < l_bit:
                if node.right:
                    res += node.right.count
            elif x1 == l_bit:
                res += dfs(node.right, bit-1, 1)
            else:
                pass
            return res
        return dfs(self.root, 31, 1)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    q = int(data[0])
    index = 1
    trie = Trie()
    output = []
    for _ in range(q):
        event = data[index]
        if event == '1':  # add warrior
            pi = int(data[index+1])
            trie.add(pi)
            index += 2
        elif event == '2':  # remove warrior
            pi = int(data[index+1])
            trie.remove(pi)
            index += 2
        elif event == '3':  # query commander
            pi = int(data[index+1])
            li = int(data[index+2])
            cnt = trie.count_leq(pi, li)
            output.append(str(cnt))
            index += 3
    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    main()
"}

