MOD = 998244353

def solve() -> None:
    S = input().strip()
    T = input().strip()

    n = len(S)
    m = len(T)

    dp = [0] * (n + 1)
    dp[0] = 1  # base case: 1 way to have empty prefix

    for i in range(1, n + 1):
        dp[i] = dp[i - 1] * 2 % MOD  # 2 ways to add the i-th character (front or back)

    # Now check if we can form T as a prefix
    result = 0
    for k in range(1, n + 1):
        if dp[k] and k <= m and sorted(S[:k]) == sorted(T[:k]):
            result = (result + dp[k]) % MOD

    print(result)

if __name__ == "__main__":
    solve()
