def is_prime(num):
    """Check if a number is prime."""
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def solve():
    n = int(input().strip())
    a = list(map(int, input().strip().split()))

    evens = [num for num in a if num % 2 == 0]
    odds = [num for num in a if num % 2 != 0]

    max_size = 1
    best_subset = []

    # Strategy 1: Use only odds
    if len(odds) >= 1:
        # Check if we can take all odds
        valid = True
        for i in range(len(odds)):
            for j in range(i + 1, len(odds)):
                if not is_prime(odds[i] + odds[j]):
                    valid = False
                    break
            if not valid:
                break
        if valid:
            max_size = len(odds)
            best_subset = odds[:]

    # Strategy 2: Use one even and some odds
    for even in evens:
        # Try to find the best combination with this even
        temp_odds = [num for num in odds if num % 2 != 0]

        # Check if we can take all these odds with this even
        valid = True
        for odd in temp_odds:
            if not is_prime(even + odd):
                valid = False
                break
        if valid:
            current_size = 1 + len(temp_odds)
            if current_size > max_size:
                max_size = current_size
                best_subset = [even] + temp_odds[:]

    # Strategy 3: Use only evens (limited, since sum of two evens is even > 2)
    # So we can only pick at most 1 even
    if len(evens) >= 1:
        if len(best_subset) == 0 or 1 > len(best_subset):
            max_size = 1
            best_subset = evens[:1]

    print(max_size)
    if max_size > 0:
        print(' '.join(map(str, best_subset)))

solve()
