import math

MOD = 1000000007

def solve():
    k = int(input())
    colors = [int(input()) for _ in range(k)]

    # Calculate factorial up to sum(colors)
    total_balls = sum(colors)
    fact = [1] * (total_balls + 1)
    for i in range(1, total_balls + 1):
        fact[i] = (fact[i-1] * i) % MOD

    # Calculate combinations using factorial
    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * pow(fact[k] * fact[n - k] % MOD, MOD - 2, MOD) % MOD

    # Using dynamic programming approach
    dp = [1] * (total_balls + 1)

    # For each color, update dp
    for c in colors:
        new_dp = [0] * (total_balls + 1)
        for total in range(total_balls + 1):
            # The last ball of this color must come before the last ball of any subsequent color
            # So we need to place it in the sequence such that there are enough balls left
            for i in range(total + 1):
                # Place c balls for this color
                if i >= c:
                    new_dp[total] = (new_dp[total] + dp[total - i] * comb(total - i, c - 1)) % MOD
        dp = new_dp

    print(dp[total_balls])

if __name__ == "__main__":
