import sys

def get_divisors(n):
    """Return all positive divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

n = int(sys.stdin.readline())
queries = []
for _ in range(n):
    xi, yi = map(int, sys.stdin.readline().split())
    queries.append((xi, yi))

answers = []
for idx in range(n):
    xi, yi = queries[idx]

    # Get divisors of xi
    divisors = get_divisors(xi)

    # If yi = 0, just count all divisors
    if yi == 0:
        answers.append(len(divisors))
        continue

    # Otherwise, check divisors against previous numbers in the range
    count = 0
    for d in divisors:
        # Check if d divides any of the numbers in the range [xi - yi, xi - 1]
        divides_any = False
        for num in range(xi - yi, xi):
            if num % d == 0:
                divides_any = True
                break
        if not divides_any:
            count += 1

    answers.append(count)

# Print answers
for ans in answers:
    print(ans)
