def count_lucky_digits(n):
    """Count the number of lucky digits (4 or 7) in n"""
    return str(n).count('4') + str(n).count('7')

def solve():
    m = int(input())

    # Count numbers with 0, 1, 2, ... lucky digits
    count = {}
    for num in range(1, m + 1):
        lucky = count_lucky_digits(num)
        if lucky not in count:
            count[lucky] = 0
        count[lucky] += 1

    # For each possible number of lucky digits k for LEP
    MOD = 1000000007
    ans = 0

    # Precompute factorials
    fact = [1] * (m + 1)
    for i in range(1, m + 1):
        fact[i] = fact[i-1] * i % MOD

    # For each k in count
    for lucky_lep, total in count.items():
        # Total ways for this lucky_lep
        total_ways = total

        # Count ways to choose 6 other numbers from remaining m - total
        # These 6 numbers must have total lucky digits <= lucky_lep - 1

        # First, count how many numbers have lucky <= lucky_lep - 1
        total_lucky_leq = 0
        for lucky, num in count.items():
            if lucky <= lucky_lep - 1:
                total_lucky_leq += num

        # Now count ways to choose 6 numbers from these total_lucky_leq
        # and assign them to parties

        # Ways = C(total_lucky_leq, 6) * 6!
        if total_lucky_leq >= 6:
            comb = fact[total_lucky_leq] * pow(fact[6], MOD-2, MOD) % MOD
            comb = comb * pow(fact[total_lucky_leq - 6], MOD-2, MOD) % MOD
        else:
            comb = 0
        ans = (ans + total_ways * comb) % MOD

    print(ans)

solve()
"}

