import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    m = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Count frequencies of remainders modulo m
    freq = [0] * m
    for num in a:
        freq[num % m] += 1

    # Find a remainder class with at least k occurrences
    found = -1
    for r in range(m):
        if freq[r] >= k:
            found = r
            break

    if found == -1:
        print("No")
    else:
        print("Yes")
        # Output k numbers from this remainder class
        # We just need to print any k of them, we can just print k times the first number
        # with this remainder
        target = found
        count = 0
        for num in a:
            if num % m == target:
                count += 1
                print(num, end=' ')
                if count == k:
                    break

if __name__ == "__main__":
    solve()
